import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 40000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errs = [];
page.on('pageerror', e => errs.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errs.push('CONSOLE ' + m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1500);
await page.click('#start-btn', { force: true });
await page.waitForTimeout(600);
// hero spot facing the centerpiece
await page.evaluate(() => {
  const p = window.__prism;
  p.player.pos.set(2, 0, 30);
  p.look(-0.05, 0.02);
});
await page.waitForTimeout(700);
await page.screenshot({ path: '/tmp/g1.jpg', type: 'jpeg', quality: 82 });

// face nearest enemy and shoot
const shootInfo = await page.evaluate(() => {
  const p = window.__prism;
  let best = null, bd = 1e9;
  for (const e of p.enemies) {
    if (!e.alive) continue;
    const d = Math.hypot(e.pos.x - p.player.pos.x, e.pos.z - p.player.pos.z);
    if (d < bd) { bd = d; best = e; }
  }
  const dx = best.pos.x - p.player.pos.x, dz = best.pos.z - p.player.pos.z;
  const d = Math.hypot(dx, dz);
  const yaw = Math.atan2(-dx, -dz);
  const dy = (best.pos.y + best.cfg.bodyY) - (p.player.pos.y + 1.66);
  const pitch = Math.atan2(dy, d);
  p.look(yaw, pitch);
  return { type: best.type, dist: d, hp: best.hp, x: best.pos.x, z: best.pos.z };
});
await page.waitForTimeout(250);
await page.evaluate(() => { const p = window.__prism; p.fire(); p.fire(); p.fire(); p.fire(); });
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/g2.jpg', type: 'jpeg', quality: 82 });
const afterShoot = await page.evaluate(() => {
  const p = window.__prism;
