input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 40000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errs = [];
page.on('pageerror', e => errs.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errs.push('CONSOLE ' + m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1200);
await page.click('#start-btn', { force: true });
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/h1.jpg', type: 'jpeg', quality: 82 });
const startPos = await page.evaluate(() => { const p = window.__prism; return { x: p.player.pos.x, z: p.player.pos.z, yaw: p.player.yaw }; });
// walk
await page.keyboard.down('w');
await page.waitForTimeout(1100);
await page.keyboard.up('w');
const walkPos = await page.evaluate(() => { const p = window.__prism; return { x: p.player.pos.x, z: p.player.pos.z, movespeed: p.player.moveSpeed }; });
// switch weapons/reload
await page.keyboard.press('2');
await page.waitForTimeout(200);
const w2 = await page.evaluate(() => ({ name: document.getElementById('weapon-name').textContent, ammo: document.getElementById('ammo').textContent, active: window.__prism.weapons.active }));
await page.keyboard.press('r');
await page.waitForTimeout(300);
const reloading = await page.evaluate(() => document.getElementById('reload').className);
await page.keyboard.press('1');
// damage all enemies then ult to finish
await page.evaluate(() => {
  const p = window.__prism;
  for (const e of p.enemies) e.hp = 30;
  p.player.ult = 100;
  const c = p.enemies[0];
  const dx = c.pos.x - p.player.pos.x, dz = c.pos.z - p.player.pos.z;
  p.look(Math.atan2(-dx, -dz), 0);
  p.doUlt();
});
await page.waitForTimeout(380);
await page.screenshot({ path: '/tmp/h2.jpg', type: 'jpeg', quality: 82 });
await page.waitForTimeout(1000);
// finish remaining by firing
await page.evaluate(() => {
  const p = window.__prism;
  for (const e of p.enemies) if (e.alive) { e.hp = 1; }
  // brute force: call damage through shots at each
  for (const e of p.enemies) {
    if (!e.alive) continue;
    const dx = e.pos.x - p.player.pos.x, dz = e.pos.z - p.player.pos.z;
    p.look(Math.atan2(-dx, -dz), Math.atan2(1.2 - 1.66, Math.hypot(dx, dz)));
    p.fire();
  }
});
await page.waitForTimeout(1800);
const result = await page.evaluate(() => ({
  mode: window.__prism.phase.mode, kills: window.__prism.phase.kills, alive: window.__prism.enemies.filter(e => e.alive).length,
  overlay: document.getElementById('result-overlay').className, title: document.getElementById('result-title').textContent,
  acc: document.getElementById('final-accuracy').textContent
}));
await page.screenshot({ path: '/tmp/h3.jpg', type: 'jpeg', quality: 82 });
// restart, pause
await page.click('#restart-btn', { force: true });
await page.waitForTimeout(500);
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
const pause = await page.evaluate(() => ({ mode: window.__prism.phase.mode, overlay: document.getElementById('pause-overlay').className }));
await page.screenshot({ path: '/tmp/h4.jpg', type: 'jpeg', quality: 82 });
console.log(JSON.stringify({ startPos, walkPos, w2, reloading, result, pause, errs }, null, 2));
await browser.close();

input.newString:
  hurt: (n) => hurtPlayer(n),
  damage: (e, n) => damageEnemy(e, n, false, null, null),
  end: endGame
};

