import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 40000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errs = [];
page.on('pageerror', e => errs.push(e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1000);
await page.click('#start-btn', { force: true });
await page.waitForTimeout(500);
// pause
await page.keyboard.press('Escape');
await page.waitForTimeout(400);
const paused = await page.evaluate(() => ({ mode: window.__prism.phase.mode, ov: document.getElementById('pause-overlay').className, timer: document.getElementById('timer').textContent }));
await page.screenshot({ path: '/tmp/pause.jpg', type: 'jpeg', quality: 82 });
await page.click('#resume-btn', { force: true });
await page.waitForTimeout(400);
const resumed = await page.evaluate(() => ({ mode: window.__prism.phase.mode, ov: document.getElementById('pause-overlay').className }));
// win
await page.evaluate(() => { const p = window.__prism; for (const e of p.enemies) p.damage(e, 999); });
await page.waitForTimeout(4000);
const won = await page.evaluate(() => ({
  mode: window.__prism.phase.mode, kills: window.__prism.phase.kills,
  ov: document.getElementById('result-overlay').className, kicker: document.getElementById('result-kicker').textContent,
  killsTxt: document.getElementById('final-kills').textContent, time: document.getElementById('final-time').textContent,
  acc: document.getElementById('final-accuracy').textContent, hud: document.getElementById('hud').className
}));
await page.screenshot({ path: '/tmp/win2.jpg', type: 'jpeg', quality: 82 });
// restart
await page.click('#restart-btn', { force: true });
await page.waitForTimeout(600);
const restarted = await page.evaluate(() => ({ mode: window.__prism.phase.mode, kills: window.__prism.phase.kills, hp: window.__prism.player.health, alive: window.__prism.enemies.filter(e => e.alive).length, hud: document.getElementById('hud').className }));
await page.screenshot({ path: '/tmp/restart.jpg', type: 'jpeg', quality: 82 });
console.log(JSON.stringify({ paused, resumed, won, restarted, errs }, null, 2));
await browser.close();

