input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 40000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errs = [];
page.on('pageerror', e => errs.push(e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1200);
await page.click('#start-btn', { force: true });
await page.waitForTimeout(2600);
await page.evaluate(() => {
  const p = window.__prism;
  const e = p.enemies.find(x => x.alive);
  p.player.pos.set(e.pos.x + 5, 0, e.pos.z + 3);
  const dx = e.pos.x - p.player.pos.x, dz = e.pos.z - p.player.pos.z;
  p.look(Math.atan2(-dx, -dz), -0.03);
  window.__target = e;
});
await page.waitForTimeout(700);
await page.evaluate(() => { const p = window.__prism; p.fire(); });
await page.waitForTimeout(16);
await page.screenshot({ path: '/tmp/c1.jpg', type: 'jpeg', quality: 84 });
await page.waitForTimeout(350);
await page.screenshot({ path: '/tmp/c2.jpg', type: 'jpeg', quality: 84 });
const info = await page.evaluate(() => ({
  target: { type: window.__target.type, hp: window.__target.hp, bar: window.__target.bar.visible },
  ammo: window.__prism.player.ammo[0],
  hits: window.__prism.phase.hits
}));
// reload test: empty the mag and press R
await page.evaluate(() => { const p = window.__prism; p.player.ammo[0] = 2; p.player.reloadT = 0; p.reload(); });
await page.waitForTimeout(200);
const reloadState = await page.evaluate(() => ({ cls: document.getElementById('reload').className, ammo: window.__prism.player.ammo[0], rt: window.__prism.player.reloadT }));
await page.waitForTimeout(2400);
const afterReload = await page.evaluate(() => ({ ammo: window.__prism.player.ammo[0], reserve: window.__prism.player.reserve[0], cls: document.getElementById('reload').className }));
// ult close
await page.evaluate(() => { const p = window.__prism; p.player.ult = 100; p.doUlt(); });
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/c3.jpg', type: 'jpeg', quality: 84 });
await page.waitForTimeout(1400);
await page.screenshot({ path: '/tmp/c4.jpg', type: 'jpeg', quality: 84 });
console.log(JSON.stringify({ info, reloadState, afterReload, errs }, null, 2));
await browser.close();

