import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 40000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errs = [];
page.on('pageerror', e => errs.push(e.message));
page.on('console', m => { if (m.type() === 'error') errs.push('CONSOLE ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errs.push('HTTP ' + r.status() + ' ' + r.url()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1800);
await page.screenshot({ path: '/tmp/final-menu.jpg', type: 'jpeg', quality: 84 });
await page.click('#start-btn', { force: true });
await page.waitForTimeout(2800);
await page.screenshot({ path: '/tmp/final-hero.jpg', type: 'jpeg', quality: 84 });
// combat setup
await page.evaluate(() => {
  const p = window.__prism;
  const e = p.enemies.find(x => x.alive);
  e.pos.set(6, 0, 11); e.home.copy(e.pos); e.group.position.copy(e.pos);
  p.player.pos.set(6, 0, 23);
  const dx = e.pos.x - p.player.pos.x, dz = e.pos.z - p.player.pos.z;
  p.look(Math.atan2(-dx, -dz), Math.atan2(1.05 - 1.66, Math.hypot(dx, dz)));
  window.__target = e;
});
await page.waitForTimeout(600);
await page.evaluate(() => { const p = window.__prism; p.fire(); });
await page.waitForTimeout(110);
await page.screenshot({ path: '/tmp/final-combat.jpg', type: 'jpeg', quality: 84 });
// ultimate
await page.evaluate(() => { const p = window.__prism; p.player.ult = 100; p.player.ultActive = 0; p.doUlt(); });
await page.waitForTimeout(380);
await page.screenshot({ path: '/tmp/final-ult.jpg', type: 'jpeg', quality: 84 });
await page.waitForTimeout(1600);
await page.screenshot({ path: '/tmp/final-ult2.jpg', type: 'jpeg', quality: 84 });
// result
await page.evaluate(() => { const p = window.__prism; for (const e of p.enemies) if (e.alive) p.damage(e, 999); });
await page.waitForTimeout(3200);
await page.screenshot({ path: '/tmp/final-result.jpg', type: 'jpeg', quality: 84 });
const state = await page.evaluate(() => ({
  mode: window.__prism.phase.mode,
  result: document.getElementById('result-kicker').textContent,
  kills: document.getElementById('final-kills').textContent,
  time: document.getElementById('final-time').textContent,
  acc: document.getElementById('final-accuracy').textContent,
  hud: document.getElementById('hud').className,
  errs: []
}));
console.log(JSON.stringify({ state, errs }, null, 2));
await browser.close();

