input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 40000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errs = [];
page.on('pageerror', e => errs.push(e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(900);
await page.click('#start-btn', { force: true });
await page.waitForTimeout(700);
await page.evaluate(() => { window.__prism.player.health = 1; window.__prism.player.armor = 0; window.__prism.player.invuln = 0; window.__prism.hurt(30); });
await page.waitForTimeout(700);
const dead = await page.evaluate(() => ({ mode: window.__prism.phase.mode, kicker: document.getElementById('result-kicker').textContent, title: document.getElementById('result-title').textContent, copy: document.getElementById('result-copy').textContent }));
await page.screenshot({ path: '/tmp/lose.jpg', type: 'jpeg', quality: 84 });
await page.click('#restart-btn', { force: true });
await page.waitForTimeout(600);
const restarted = await page.evaluate(() => ({ mode: window.__prism.phase.mode, hp: window.__prism.player.health, kills: window.__prism.phase.kills, alive: window.__prism.enemies.filter(e => e.alive).length }));
await page.evaluate(() => { window.__prism.phase.time = 0.4; });
await page.waitForTimeout(1100);
const timeout = await page.evaluate(() => ({ mode: window.__prism.phase.mode, kicker: document.getElementById('result-kicker').textContent, title: document.getElementById('result-title').textContent, copy: document.getElementById('result-copy').textContent }));
await page.screenshot({ path: '/tmp/timeout.jpg', type: 'jpeg', quality: 84 });
console.log(JSON.stringify({ dead, restarted, timeout, errs }, null, 2));
await browser.close();

