content.text:
.touch-controls{display:none}
.touch-ult,.touch-reload,.touch-weapon{display:none;position:absolute;pointer-events:auto;touch-action:none;border-radius:50%;color:var(--teal);background:rgba(6,23,25,.62);border:1px solid rgba(104,246,220,.46);font:11px var(--mono)}
.touch-controls{display:none}
.touch-controls{opacity:0}
.touch-controls{display:block;position:absolute;inset:0;pointer-events:none}
.touch-stick{position:absolute;left:20px;bottom:100px;width:112px;height:112px;border-radius:50%;border:1px solid rgba(131,229,212,.28);background:rgba(6,25,27,.28);pointer-events:auto;touch-action:none}
.touch-fire,.touch-jump,.touch-dash,.touch-scan{position:absolute;pointer-events:auto;touch-action:none;border-radius:50%;color:var(--teal);background:rgba(6,23,25,.6);border:1px solid rgba(104,246,220,.46);font:15px var(--mono)}
.touch-fire{right:21px;bottom:103px;width:69px;height:69px;font-size:27px;display:block}
.touch-jump{right:98px;bottom:112px;width:43px;height:43px;display:block}
.touch-dash{right:97px;bottom:164px;width:38px;height:38px;font-size:11px;display:block}
.touch-scan{right:23px;bottom:183px;width:35px;height:35px;font-size:11px;display:block}
.touch-ult{right:24px;bottom:226px;width:33px;height:33px;font-size:11px;display:block;color:#ffb095;border-color:rgba(255,123,90,.6)}
.touch-reload{right:99px;bottom:212px;width:34px;height:34px;font-size:11px;display:block}
.touch-weapon{right:24px;bottom:270px;width:33px;height:33px;font-size:14px;display:block}
.touch-ult.charged{background:rgba(255,95,70,.5);color:#fff;box-shadow:0 0 20px rgba(255,110,80,.75),inset 0 0 10px rgba(255,200,180,.4);border-color:#ffd0c0;animation:ult-pulse 1.2s infinite}

