import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const cfg = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim();
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 40000 });
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', e => errs.push(e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1400);
await page.screenshot({ path: '/tmp/menu-m.jpg', type: 'jpeg', quality: 84 });
await page.tap('#start-btn');
await page.waitForTimeout(1200);
const start = await page.evaluate(() => ({ x: window.__prism.player.pos.x, z: window.__prism.player.pos.z, w: window.__prism.weapons.active }));
// simulate joystick drag
const drag = await page.evaluate(() => {
  const stick = document.getElementById('touch-stick');
  const r = stick.getBoundingClientRect();
  const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
  const mk = (x, y) => new Touch({ identifier: 7, target: stick, clientX: x, clientY: y, pageX: x, pageY: y, radiusX: 4, radiusY: 4, force: 1 });
  const t = (type, x, y) => stick.dispatchEvent(new TouchEvent(type, { bubbles: true, cancelable: true, touches: type === 'touchend' ? [] : [mk(x, y)], changedTouches: [mk(x, y)] }));
  t('touchstart', cx, cy); t('touchmove', cx, cy - 40);
  return { x: window.__prism.input.touchMove.x, y: window.__prism.input.touchMove.y };
});
await page.waitForTimeout(1200);
const moved = await page.evaluate(() => {
  const stick = document.getElementById('touch-stick');
  const r = stick.getBoundingClientRect();
  const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
  const mk = (x, y) => new Touch({ identifier: 7, target: stick, clientX: x, clientY: y, pageX: x, pageY: y, radiusX: 4, radiusY: 4, force: 1 });
  stick.dispatchEvent(new TouchEvent('touchend', { bubbles: true, cancelable: true, touches: [], changedTouches: [mk(cx, cy)] }));
  return { x: window.__prism.player.pos.x, z: window.__prism.player.pos.z, inputX: window.__prism.input.touchMove.x };
});
// fire tap
const ammoBefore = await page.evaluate(() => window.__prism.player.ammo[0]);
await page.tap('#touch-fire');
await page.waitForTimeout(700);
const ammoAfter = await page.evaluate(() => window.__prism.player.ammo[0]);
// weapon swap
await page.tap('#touch-weapon');
await page.waitForTimeout(350);
const swapped = await page.evaluate(() => ({ w: window.__prism.weapons.active, name: document.getElementById('weapon-name').textContent }));
// dash
await page.tap('#touch-dash');
await page.waitForTimeout(300);
const dashed = await page.evaluate(() => ({ cd: window.__prism.player.dashCD, dashT: window.__prism.player.dashT }));
// ult charged tap
await page.evaluate(() => { window.__prism.player.ult = 100; });
await page.waitForTimeout(250);
const ultBtn = await page.evaluate(() => ({ txt: document.getElementById('touch-ult').textContent, charged: document.getElementById('touch-ult').className }));
await page.tap('#touch-ult');
await page.waitForTimeout(500);
const ult = await page.evaluate(() => ({ active: window.__prism.player.ultActive, ult: window.__prism.player.ult }));
await page.screenshot({ path: '/tmp/play-m.jpg', type: 'jpeg', quality: 84 });
console.log(JSON.stringify({ start, drag, moved, ammoBefore, ammoAfter, swapped, dashed, ultBtn, ult, errs }, null, 2));
await browser.close();

