    hud: { z: hs.zIndex, pe: hs.pointerEvents, cls: hud.className },
    el: el ? (el.id || el.className || el.tagName) : null,
    at: r.left + r.width / 2 + ',' + (r.top + r.height / 2),
    vh: innerHeight, vw: innerWidth,
    bodyCls: document.body.className
  };
}));
