cat >> style.css <<'EOF'

/* ---------- global touch layout (all sizes) ---------- */
body.is-touch .touch-controls{display:block;position:absolute;inset:0;pointer-events:none}
body.is-touch .touch-stick{position:absolute;left:20px;bottom:100px;width:112px;height:112px;border-radius:50%;border:1px solid rgba(131,229,212,.28);background:rgba(6,25,27,.3);pointer-events:auto;touch-action:none}
body.is-touch .touch-stick:before{content:'';position:absolute;left:50%;top:50%;width:3px;height:3px;background:rgba(151,230,217,.35);transform:translate(-50%,-50%);border-radius:50%}
body.is-touch .touch-stick i{position:absolute;left:36px;top:36px;width:40px;height:40px;border-radius:50%;background:rgba(104,246,220,.23);border:1px solid rgba(104,246,220,.54)}
body.is-touch .bottom-center{display:none!important}
body.is-touch .weapon-slots{display:none!important}
body.is-touch .bottom-right{left:50%;right:auto;transform:translateX(-50%);bottom:10px;width:136px;text-align:center}
body.is-touch .weapon-status{justify-content:center;gap:6px}
body.is-touch .ammo-row{justify-content:center;height:36px}
body.is-touch .ammo-count b{font-size:31px}
body.is-touch .player-tag{display:none}
body.is-touch .bottom-left{bottom:26px}
body.is-touch .banner-controls{display:flex;flex-wrap:nowrap;justify-content:center;max-width:360px;gap:9px;font-size:7.5px;line-height:1.4;letter-spacing:.4px;color:#d5e8e3;background:rgba(4,16,18,.55);border:1px solid rgba(104,246,220,.18);padding:7px 10px;white-space:nowrap}
body.is-touch .banner-controls span{display:inline;color:#d5e8e3}
@media(orientation:landscape) and (max-height:540px){
  body.is-touch .touch-ult{right:20px;bottom:170px}
  body.is-touch .touch-scan{right:20px;bottom:128px}
  body.is-touch .touch-reload{right:94px;bottom:156px}
  body.is-touch .touch-dash{right:94px;bottom:102px}
  body.is-touch .touch-jump{right:94px;bottom:50px}
  body.is-touch .touch-fire{right:20px;bottom:44px;width:58px;height:58px;font-size:24px}
  body.is-touch .touch-weapon{right:20px;bottom:210px}
  body.is-touch .touch-stick{left:20px;bottom:50px;width:100px;height:100px}
  body.is-touch .touch-stick i{left:32px;top:32px;width:36px;height:36px}
  body.is-touch .bottom-right{bottom:6px}
  .hud .minimap-wrap{top:100px;width:142px}
  .hud #minimap{width:126px;height:126px}
}
EOF
